<template>
<div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="mb-1">Supplier purchase orders</h4><div class="text-muted small">Create → approval → receive into batch-wise stock.</div></div><button class="btn btn-success" @click="showForm=!showForm"><i class="bi bi-plus-lg me-1"></i>New purchase order</button></div>
<div v-if="showForm" class="card mb-3"><div class="card-header fw-semibold">New purchase order</div><form class="card-body row g-3" @submit.prevent="create"><div class="col-md-4"><label class="form-label">Supplier *</label><select v-model.number="form.supplier_id" class="form-select" required><option value="">Select supplier</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div class="col-md-4"><label class="form-label">Order date *</label><input v-model="form.order_date" type="date" class="form-control" required></div><div class="col-md-4"><label class="form-label">Expected delivery</label><input v-model="form.expected_date" type="date" class="form-control"></div>
<div class="col-12"><div class="d-flex justify-content-between"><b>Order items</b><button type="button" class="btn btn-sm btn-outline-success" @click="addLine">Add medicine</button></div><div v-for="(line,i) in form.items" :key="i" class="row g-2 mt-1 align-items-end"><div class="col-lg-3"><label class="form-label small">Medicine</label><select v-model.number="line.medicine_id" class="form-select form-select-sm" required><option value="">Select medicine</option><option v-for="m in medicines" :key="m.id" :value="m.id">{{m.name}} {{m.strength}}</option></select></div><div class="col-6 col-lg-1"><label class="form-label small">Packs</label><input v-model.number="line.quantity" type="number" min="1" class="form-control form-control-sm"></div><div class="col-6 col-lg-1"><label class="form-label small">Bonus</label><input v-model.number="line.bonus_qty" type="number" min="0" class="form-control form-control-sm"></div><div class="col-12 col-lg-2"><label class="form-label small">Manufacturer scheme</label><select v-model="line.scheme_id" class="form-select form-select-sm"><option value="">No scheme</option><option v-for="s in schemes" :key="s.id" :value="s.id">{{s.name}}</option></select><small v-if="line.scheme_id" class="text-success">+{{schemeFree(line)}} free</small></div><div class="col-6 col-lg-2"><label class="form-label small">Purchase / pack</label><input v-model.number="line.purchase_price" type="number" min="0" step=".01" class="form-control form-control-sm"></div><div class="col-6 col-lg-2"><label class="form-label small">Sale / pack</label><input v-model.number="line.sale_price" type="number" min="0" step=".01" class="form-control form-control-sm"></div><div class="col-6 col-lg-1"><label class="form-label small">Batch</label><input v-model="line.batch_no" class="form-control form-control-sm"></div><div class="col-6 col-lg-1"><label class="form-label small">Expiry</label><input v-model="line.expiry_date" type="date" class="form-control form-control-sm"></div><div class="col-lg-1"><button type="button" class="btn btn-sm btn-outline-danger" @click="form.items.splice(i,1)"><i class="bi bi-trash"></i></button></div></div></div>
<div class="col-md-3"><label class="form-label">Discount</label><input v-model.number="form.discount" type="number" min="0" step=".01" class="form-control"></div><div class="col-md-3"><label class="form-label">Tax amount</label><input v-model.number="form.tax" type="number" min="0" step=".01" class="form-control"></div><div class="col-md-6"><label class="form-label">Notes</label><input v-model="form.notes" class="form-control"></div><div class="col-12 text-end"><button type="button" class="btn btn-light me-2" @click="showForm=false">Cancel</button><button class="btn btn-success" :disabled="saving">Submit for approval</button></div></form></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Order</th><th>Supplier</th><th>Branch</th><th>Date</th><th>Total</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td><b>{{o.order_no}}</b></td><td>{{o.supplier?.name}}</td><td>{{o.branch?.name}}</td><td>{{o.order_date}}</td><td>{{money(o.total)}}</td><td><span class="badge" :class="o.status==='approved'?'bg-success':o.status==='rejected'?'bg-danger':'bg-secondary'">{{o.status}}</span></td><td class="text-end"><button v-if="o.status==='pending_approval'" class="btn btn-sm btn-outline-success me-1" @click="review(o,'approve')">Approve</button><button v-if="o.status==='pending_approval'" class="btn btn-sm btn-outline-danger me-1" @click="review(o,'reject')">Reject</button><button v-if="o.status==='approved'" class="btn btn-sm btn-success" @click="receive(o)">Receive stock</button></td></tr><tr v-if="!rows.length"><td colspan="7" class="text-center text-muted py-4">No purchase orders yet.</td></tr></tbody></table></div><div class="card-footer small text-muted">Receiving creates a normal purchase, updates supplier balance and creates FEFO batches. A purchase order alone does not change stock.</div></div></div>
</template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import api from '../api';import {money} from '../utils/format';import {Swal} from '../utils/swal';
const rows=ref([]),suppliers=ref([]),medicines=ref([]),schemes=ref([]),showForm=ref(false),saving=ref(false);const blankLine=()=>({medicine_id:'',quantity:1,bonus_qty:0,scheme_id:'',purchase_price:0,sale_price:0,batch_no:'',expiry_date:''});const form=reactive({supplier_id:'',order_date:new Date().toISOString().slice(0,10),expected_date:'',discount:0,tax:0,notes:'',items:[blankLine()]});
async function load(){const [o,l,m,s]=await Promise.all([api.get('/purchase-orders'),api.get('/lookups'),api.get('/medicines',{params:{per_page:100}}),api.get('/stage4/schemes')]);rows.value=o.data.data||[];suppliers.value=l.data.suppliers||[];medicines.value=m.data.data||[];schemes.value=(s.data.data||[]).filter(x=>x.is_active&&x.scheme_type==='buy_x_get_y'&&String(x.valid_from).slice(0,10)<=new Date().toISOString().slice(0,10)&&String(x.valid_to).slice(0,10)>=new Date().toISOString().slice(0,10));}function addLine(){form.items.push(blankLine());}function schemeFree(line){const s=schemes.value.find(x=>Number(x.id)===Number(line.scheme_id));if(!s)return 0;let n=Math.floor(Number(line.quantity||0)/Math.max(1,Number(s.buy_quantity)||1))*Number(s.free_quantity||0);return s.max_free_quantity?Math.min(n,Number(s.max_free_quantity)):n;}async function create(){saving.value=true;try{await api.post('/purchase-orders',form);showForm.value=false;form.items=[blankLine()];await load();}finally{saving.value=false;}}async function review(o,decision){const r=await Swal.fire({title:`${decision} ${o.order_no}?`,input:'text',inputLabel:'Optional note',showCancelButton:true,confirmButtonText:'Confirm'});if(!r.isConfirmed)return;await api.post(`/purchase-orders/${o.id}/review`,{decision,note:r.value});await load();}async function receive(o){const r=await Swal.fire({title:'Receive purchase order',text:'Enter amount paid now. Remaining amount becomes supplier payable.',input:'number',inputValue:0,inputAttributes:{min:0,step:'.01'},showCancelButton:true,confirmButtonText:'Receive stock'});if(!r.isConfirmed)return;await api.post(`/purchase-orders/${o.id}/receive`,{paid:Number(r.value)||0,payment_method:'cash'});await load();}onMounted(load);
</script>
